const triggerData = $input.item.json || {};
const body = triggerData.body || triggerData.payload || triggerData || {};
const pessoaId = body.pessoa_id ? parseInt(body.pessoa_id, 10) : null;
const isInterno = Boolean(body.is_interno);

if (!pessoaId || !Number.isFinite(pessoaId)) {
  return { json: { hasError: true, error: 'pessoa_id inválido ou não informado.' } };
}

return {
  json: {
    hasError: false,
    pessoaId,
    isInterno
  }
};

const prep = $('Preparar Parametros').first()?.json || {};
if (prep.hasError) {
  return { json: { ok: false, message: prep.error } };
}

const row = $input.first()?.json || {};
if (!row.id) {
  return { json: { ok: false, message: 'Contato não encontrado.' } };
}

return {
  json: {
    ok: true,
    pessoa_id: row.id,
    is_interno: Boolean(row.metadata_json?.is_interno)
  }
};
